SELECT  FROM crm_settlement_batch WHERE tenant_id=#{tenantId}

AND settlement_type=#{type}
AND status=#{status}
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM crm_settlement_batch WHERE tenant_id=#{tenantId}

AND settlement_type=#{type}
AND status=#{status}

SELECT id,institution_id AS institutionId,status,service_at AS serviceAt FROM crm_redemption
WHERE tenant_id=#{tenantId} AND id IN #{id}
ORDER BY id FOR UPDATE
